  v = `Необов’язково: ви можете запропонувати іншим розробникам включити свої ігри до вашого комплекту. Ви як власник комплекту відповідальні за координацію з іншими розробниками, і лише ви маєте можливість опублікувати комплект у крамниці Steam. Запрошені розробники мають обрати, які ігри чи пакунки увійдуть до складу комплекту. Щоразу, коли пакунок додається до комплекту або змінюється відсоток знижки, всі учасники співпраці мають схвалити включення своєї гри до складу комплекту — лише після цього можна буде опублікувати його.`,
