  D = `Тут можна знайти всі активні й підготовлені сторінки розпродажів, створені Valve або схваленим стороннім партнером. Щоб дозволити новому партнеру створювати власні сторінки розпродажів — %1$s. Ви можете переслати своєму партнерові %2$s.`,
