  ct = `Розпродаж має бути створений у домівці творця, що також відома як сторінка розробника, видавця чи франшизи. Знайдіть назву домівки творця нижче:`,
  lt = `Введіть назву групи, що пов’язана з домашньою сторінкою творця, або посилання на сторінку в крамниці, якщо це для куратора чи нещодавно створеної групи спільноти.`,
  ut = `1. Творець, обраний для проведення розпродажу:`,
