  pt = `Для використання функції розпродажу домівці творця слід приєднайтеся до бети подій для партнерів. Скасувати цю дію неможливо. У результаті буде змінено редактора публікації оголошень, що більше не зможе створювати пов’язані оголошення. %1$s`,
  mt = `3. Надайте мінімально необхідну інформацію:`,
  ht = `Описова назва події`,
  gt = `Це повна назва події, яку побачать користувачі. Сюди можна включити партнера й дати події`,
