  mb = `Щоб уникнути повторень та покращити читабельність, не додавайте назву гри разом з пробілами та такими символами для розділення тексту, як двокрапка і тире, на початку назви продуктів типу завантажуваного вмісту чи саундтреку, якщо вони є в області купівлі пакунка. Наприклад, Half Life 2: Episode One буде показано як Episode One. Система приховає лише назву основної гри, пробіли та звичні символи для розділення тексту, як-от тире і двокрапку.`,
