  Tw = `Рекомендовані ціни`,
  Ew = `Щоб допомогти вам керувати цінами в більш ніж 35 різних валютах, які підтримує Steam, цей інструмент пропонує метод конвертації базової ціни у доларах США в місцеву валюту різних регіонів. В основу цієї конвертації покладена комбінація вартості валюти, регіональної купівельної спроможності, обов’язкових податків і нашого досвіду продажів у конкретних регіонах.`,
  Dw = `Натиснувши на кнопку нижче, ви застосуєте конвертовані ціни до всіх видимих пакунків, окрім прихованих за допомогою згортання рядків або введення текстового фільтра.`,
