  lE = `Поточна ціна нижча за ту, яку зазвичай можна встановити в цій валюті. Ви можете залишити її такою, як є, однак це обмежить відсоток знижки, яку ви можете встановити на свою гру, для підтримання ціни зі знижкою вищою за дозволену мінімальну суму трансакції.`,
