  gE = `Враховуючи вибраний метод конвертації та ціну в доларах США, введена ціна значно нижча за рекомендовану (%1$s).`,
  _E = `Враховуючи вибраний метод конвертації та ціну в доларах США, введена ціна значно нижча за рекомендовану (%1$s). Така ціна обмежить максимальний розмір знижок до %1$s%, щоб ціна зі знижкою не була меншою ніж 0,49 долара США.`,
