  CO = `Використання: капсула «У центрі уваги» з’являється вгорі домашньої сторінки Steam і відповідного центру вмісту для конкретних пропозицій, як-от «Акція серед тижня» чи «Акція на вихідних».`,
  wO = `Дизайн: у нижній частині банерів «У центрі уваги» автоматично з’являтиметься розділ з описом типу пропозиції (наприклад, «Акція на вихідних») і датою її завершення.`,
  TO = `Фактичний розмір цієї частини зображення, що буде прикрита, залежатиме від обсягу тексту та/або мови.`,
  EO = `Будь ласка, не розміщуйте ключові елементи в нижній чверті зображення.`,
