  OO = `Використання: вертикальна капсула «У центрі уваги» з’являється на домашній сторінці в розділі «Знижки та події». Це зображення потрібне лише для розпродажів серії ігор і від видавця. Якщо в розділі «У центрі уваги» буде лише одна гра, для нього автоматично використовуватиметься її вертикальна капсула крамниці.`,
  kO = `Дизайн: капсули «У центрі уваги» мають той самий розмір, що й вертикальні капсули гри.`,
