  jO = `Тут не має бути жодного додаткового тексту, як-от «Розпродаж від видавця», «Безкоштовно на вихідних», «Знижки до 90%». Локалізований банер, що відображатиметься поверх цього зображення, міститиме контекст. Єдиний виняток: текст «Розпродаж серії ігор».`,
  MO = `Тобто не слід додавати такий текст, як «Розпродаж серії ігор», «Розпродаж від видавця» чи «Безкоштовні вихідні».`,
  NO = `Залиште вільне місце у верхній частині зображення, де банер «У центрі уваги» накладатиметься на капсулу.`,
  PO = `Спливне рекламне повідомлення (%1$s)`,
  FO = `Використання: спливне вікно в Steam та головна сторінка крамниці Steam`,
  IO = `Дизайн: для кращих результатів слід зробити логотип чітким і зазначити тип акції, у якій продукт бере участь («Придбайте дочасно», «Уже в Steam», «Незабаром» тощо).`,
