  UO = `Зображення: для найкращого результату використовуйте зображення, яке представляє новий вміст оновлення, як-от нове ключове зображення, знімки екрана або нові персонажі чи функції тощо.`,
  WO = `Логотип: може бути основним логотипом з назвою гри або офіційним логотипом оновлення гри, якщо такий є. Якщо існує кілька мовних версій логотипа для локалізації, надайте їх.`,
  GO = `Не включайте додатковий текст у це зображення. Інформація про подію з оновленням та заклик до дії автоматично з’являться поруч із зображенням.`,
  KO = `Лише статичні зображення, без анімації.`,
  qO = `Формат фінального вивантаження: JPEG, PNG або GIF. Розмір файлу: < 5 МБ.`,
  JO = `Будь ласка, завжди надавайте PSD-файли з шарами.`,
  YO = `Зображення головного банера крамниці (%1$s)`,
  XO = `Зображення банера вгорі центра вмісту (%1$s)`,
  ZO = `Використання: це зображення дуже великого формату, яке розташовується вгорі головної сторінки та/або в центрі крамниці.`,
  QO = `Необхідні формати: великий і для мобільної версії. Для попереднього перегляду слід вивантажити статичні версії головного банера крамниці, навіть якщо також створюєте анімовані версії.`,
  $O = `Розмір файлів: менше ніж 5 МБ. Розширення: .jpg, .gif або .png.`,
  ek = `Зображення може мати розтушовані краї або переходити до іншого суцільного кольору, якщо основний колір занадто контрастує зі стандартним синім кольором крамниці Steam.`,
  tk = `Важливий вміст потрібно розміщувати в центрі зображення шириною 940 пікселів.`,
  nk = `Головні банери крамниці можуть бути анімованими, але анімація має бути ледь помітною. Якщо вирішите використовувати анімацію, вам слід ознайомитися з відповідною документацією за посиланням вище й дотримуватися наведених там характеристик.`,
