  ak = `Необхідні формати: великий і для мобільної версії. Обов’язкова наявність чіткого заклику до дії та дат події.`,
  ok = `Розмір файлів: менше ніж 5 МБ. Розширення: .jpg, .gif або .png.`,
  sk = `Зображення для сторінки розпродажу (%1$s)`,
  ck = `Слід врахувати, що на сторінках розпродажів є кілька різних типів зображень`,
  lk = `Зображення тла розпродажу`,
  uk = `Використання: це зображення є тлом вашої сторінки розпродажу`,
  dk = `Дизайн: лівий, правий і нижній краї повинні плавно переходити до одного суцільного кольору, що застосовуватиметься до решти сторінки. Перегляньте шаблон, щоби дізнатися більше. Якщо ви не використовуєте логотип на сторінці розпродажу, у межах безпечної зони вгорі зображення повинен бути логотип події та дати її проведення.`,
  fk = `Розмір: менше ніж 5 МБ. Розширення: .jpg або .png. Зображення має бути статичним.`,
