  gk = `Головне зображення події / попередній перегляд`,
  _k = `Використання: це зображення для показу вашої події в центрі новин Steam і на сторінці особливих пропозицій. Воно також з’являється під час попереднього перегляду, коли користувачі поширюють посилання на подію в соцмережах.`,
  vk = `Дизайн: на цьому зображенні мають бути логотип і дати події.`,
