  bk = `Використання: ця ілюстрація з’являється вгорі оголошення, пов’язаного з вашою сторінкою розпродажу.`,
  xk = `Дизайн: це зображення не є вкрай важливим — воно просто надає трохи контексту та кольору вашому письмовому оголошенню.`,
