  wk = `Використання: це зображення розташовується поверх зображення кожної гри, що бере участь у вашій події. Саме з цієї причини ви маєте спочатку отримати дозвіл від розробників кожної гри, що бере участь. Інакше використовувати цю функцію заборонено.`,
  Tk = `Дизайн: на цьому зображенні мають бути логотип і дати події. Також бажана наявність заклику до дії або короткого гасла події, що допоможуть гравцям зрозуміти контекст.`,
  Ek = `Розмір: менше ніж 5 МБ. Розширення: .jpg або .png. Зображення має бути статичним.`,
