  Ok = `Використання: це мобільна версія банера на сторінці в крамниці, яка замінює стандартну версію на екранах шириною 500 пікселів і менше.`,
  kk = `Це зображення має загалом відповідати стандартному банеру на сторінці в крамниці`,
  Ak = `Розмір: менше ніж 5 МБ. Розширення: .jpg або .png. Зображення має бути статичним.`,
  jk = `Надіслати зображення`,
  Mk = `Надіслати зображення…`,
  Nk = `Ваші зображення було надіслано Valve. Це поки все, що вам треба було зробити! Надіслані зображення автоматично з’являться на панелі команди Steam для перевірки й підготовки до акції.`,
  Pk = `Зображення надіслано!`,
  Fk = `Зображення надіслані! Більше нічого не потрібно робити.`,
  Ik = `Натисніть нижче, щоб надіслати Valve рекламні зображення. Після цього команда Steam почне їхню перевірку й підготовку до акції.`,
  Lk = `Помилка надсилання: зазначена вище адреса введена неправильно`,
