  zk = `Пропозиція діє до %1$s`,
  Bk = `Важливо! Вимоги до зображень`,
  Vk = `Перегляньте контрольний список нижче і надішліть нам необхідні зображення, щоб ми могли перекласти цю пропозицію на всі мови, які підтримує Steam!`,
  Hk = `Розмір кожного файлу має бути меншим ніж 5 МБ`,
