  Gk = `Логотип (надається перевага смартоб’єктам), окремо від ілюстрації.`,
  Kk = `Увесь текст має бути доступний для редагування в окремій теці «text» у файлі PSD, щоби наша команда змогла без проблем його локалізувати.`,
  qk = `Надішліть використані шрифти (особливо нестандартні).`,
  Jk = `Збережіть усі стилі тексту та шари в Photoshop. Не створюйте посилань на файли з інших програм, як-от Illustrator.`,
  Yk = `Для анімованих зображень також надайте безшовний циклічний файл формату MP4 чи PNG без тексту й логотипу. Текст має бути статичним і на окремому шарі, щоби його без проблем змогла локалізувати наша команда.`,
  Xk = `Щоб дізнатися більше інформації та переглянути приклади, а також вимоги до анімованих зображень, прочитайте нашу статтю <1>«Рекламні графічні елементи крамниці»</1>.`,
  Zk = `Повідомлення від представника Steam`,
  Qk = `Контрольний список зображень`,
  $k = `Вивантажити вертикальну капсулу «У центрі уваги» для попереднього перегляду`,
  eA = `Нижче ви можете вивантажити зображення для попереднього перегляду. Воно має відповідати нашим шаблонам щодо розміру та обрізання.`,
  tA = `Зображення для маркетингового повідомлення не потрібні`,
  nA = `Для маркетингового зображення буде використано наявну головну капсулу, знімки екрана й трейлер, видимі на сторінці вашої гри в крамниці.`,
  rA = `Вивантажити маркетинговий текст для попереднього перегляду`,
  iA = `Попередній перегляд: вивантажте зображення для промозастосунку`,
  aA = `Нижче ви можете вивантажити зображення для попереднього перегляду. Воно має відповідати нашим шаблонам щодо розміру та обрізання.`,
  oA = `Вивантажити для попереднього перегляду головний банер крамниці`,
  sA = `Нижче ви можете вивантажити для попереднього перегляду головний банер крамниці та його мобільну версію. Ці зображення мають відповідати нашим шаблонам щодо розміру та обрізання.`,
  cA = `Вивантажити для попереднього перегляду банер під каруселлю крамниці`,
  lA = `Нижче ви можете вивантажити для попереднього перегляду банер під каруселлю крамниці та його мобільну версію. Ці зображення мають відповідати нашим шаблонам щодо розміру та обрізання.`,
  uA = `Вивантажити для попереднього перегляду зображення сторінки розпродажу`,
  dA = `Нижче ви можете вивантажити для локалізації попередні версії п’яти зображень, які будуть на сторінці розпродажу. Ці зображення мають відповідати нашим шаблонам щодо розміру та обрізання.`,
  fA = `Особливі інструкції`,
  pA = `Введіть будь-які особливі інструкції чи додаткову інформацію про свої зображення, яку має знати ваш представник у Steam. Наприклад, чи включаєте ви інформацію про пов’язане оновлення? Чи є якісь особливі настанови щодо брендингу якогось із зображень?`,
  mA = `щось особливе, що нам слід знати про ваші зображення`,
  hA = `Контактна інформація`,
  gA = `Введіть одну або кілька адрес електронної пошти, за якими можна зв’язатися з вами в разі появи питань чи зауважень стосовно вивантажених зображень.`,
