  JA = `Якщо колір або зображення тла дуже світлі, стрілку можна не помітити. Виберіть це налаштування, щоб змінити стандартний білий колір стрілок каруселі.`,
  YA = `Якщо колір або зображення тла дуже світлі, стрілку можна не помітити. Виберіть це налаштування, щоб змінити стандартний біло-сірий колір навігаційної стежки в каруселі. Стосується головним чином менших екранів, як-от Steam Deck.`,
