  Rj = `Змінити заплановану дату випуску`,
  zj = `Найближча можлива дата виходу: щойно ми завершимо перевірку вашої збірки гри.`,
  Bj = `Найближча можлива дата виходу: %1$s`,
  Vj = `Найближча можлива дата виходу — два тижні після публікації вашої сторінки «Незабаром» в крамниці або 21 днів після першого придбання внеску за продукт (залежно від того, що настане пізніше). Плануйте відповідно.`,
  Hj = `Найближча можлива дата виходу — два тижні після публікації вашої сторінки «Незабаром» в крамниці. Плануйте відповідно.`,
  Uj = `Встановіть дату, на яку запланували випуск свого застосунку в Steam. Якщо до випуску ще багато часу, просто вкажіть приблизну. Якщо випуск потрібно буде відкласти, оновіть тут дату принаймні за два тижні до попередньо встановленої.`,
  Wj = `Ви не можете випустити свою гру на вихідних, оскільки в ці дні ніхто зі співробітників Valve не зможе допомогти з питаннями щодо випуску, які можуть виникнути.`,
  Gj = `Усі дати й час будуть вказані за тихоокеанським часовим поясом.`,
  Kj = `Ваша поточна запланована дата випуску — %1$s. Якщо вам потрібно її змінити, <1>зверніться до Valve</1> і вкажіть причину цієї зміни, а також нову заплановану дату. Ви повинні бути впевненими, що випустите свій продукт саме в цю нову дату.`,
  qj = `УВАГА: оскільки ваша сторінка «Незабаром» вже опублікована, зміна дати випуску призведе до негайної публікації вашої сторінки в крамниці для оновлення цієї дати. Усі незатверджені зміни до вашої сторінки в крамниці стануть видимими для користувачів.`,
  Jj = `УВАГА: найближча можлива дата виходу — %1$s. Ви зможете випустити продукт в будь-який момент після цієї дати, незалежно від того, якою є ваша запланована дата випуску.`,
