  eL = `Відвідування сторінки в крамниці зі сторінки фестивалю`,
  tL = `Відвідування сторінки вашої гри в крамниці зі сторінки Фестивалю новинок Steam під час події. Показується лише для ігор, у яких ви можете переглядати маркетинговий трафік.`,
  nL = `Відвідування сторінки в крамниці під час фестивалю`,
