  lL = `Фестиваль новинок Steam`,
  uL = `Щоби дізнатися більше про Фестиваль новинок Steam, перегляньте цю документацію:`,
  dL = `Документація Фестивалю новинок Steam`,
  fL = `Жодна з ваших ігор нещодавно не брала участь у Фестивалі новинок Steam.`,
  pL = `Ваші підсумки`,
  mL = `Виберіть нижче випуск Фестивалю новинок Steam для перегляду даних щодо участі вашої гри в ньому`,
  hL = `Ваші ігри:`,
  gL = `Більше продуктів (від видавця / від розробника / із франшизи)`,
  _L = `Для вашого застосунку не налаштовано жодної сторінки творця. Перегляньте документацію про <1>сторінки розробника та видавця</1> або <2>сторінки франшиз</2>, щоб налаштувати їх для свого застосунку.`,
  vL = `Виберіть пов’язану сторінку творця, з якої слід показувати предмети на сторінці в крамниці. Цей розділ з’явиться під описом гри.`,
