  CL = `Місцем в хітах продажу`,
  wL = `Спершу показувати ігри, які найкраще продаються.`,
  TL = `Датою випуску`,
  EL = `Спершу показувати найновіші релізи. На початку будуть невипущені ігри, відсортовані за вказаною датою випуску.`,
  DL = `Позначками`,
  OL = `Показувати ігри в порядку відповідності позначкам цієї гри.`,
