  AL = `Не показує список ігор від жодного з моїх видавців, розробників або франшиз.`,
  jL = `Вручну відібрати ігри для показу`,
  ML = `За бажанням ви можете вказати одну чи кілька ігор, які з’являться на початку списку над автоматично відсортованими.`,
  NL = `Додати застосунок до показуваних`,
  PL = `Показувані застосунки:`,
  FL = `Спочатку показуватимуться ці елементи. Перетягуйте їх, щоби змінити порядок.`,
  IL = `Пов’язаний творець`,
  LL = `Немає примусово показуваних застосунків.`,
  RL = `Введіть/виберіть застосунок…`,
  zL = `Капсула не доступна`,
